LL OR file_size_bytes <= 1000000) NOT VALID"},{"name":"sale_photo_evidence_height_check","definition":"CHECK (height IS NULL OR height > 0)"},{"name":"sale_photo_evidence_market_id_fkey","definition":"FOREIGN KEY (market_id) REFERENCES markets(id) ON DELETE CASCADE"},{"name":"sale_photo_evidence_mime_type_check","definition":"CHECK (mime_type IS NULL OR (mime_type = ANY (ARRAY[''image/webp''::text, ''image/jpeg''::text])))"},{"name":"sale_photo_evidence_owner_id_fkey","definition":"FOREIGN KEY (owner_id) REFERENCES profiles(id) ON DELETE CASCADE"},{"name":"sale_photo_evidence_pkey","definition":"PRIMARY KEY (id)"},{"name":"sale_photo_evidence_r2_object_key_check","definition":"CHECK (r2_object_key IS NULL OR r2_object_key ~~ ''sales-evidence/7d/%''::text AND r2_object_key !~~ ''%..%''::text AND r2_object_key !~~ ''%//%''::text)"},{"name":"sale_photo_evidence_r2_object_key_identity_check","definition":"CHECK (r2_object_key IS NULL OR r2_object_key = ((((((((''sales-evidence/7d/''::text || owner_id::text) || ''/''::text) || market_id::text) || ''/''::text) || sale_id::text) || ''/''::text) || id::text) || ''.webp''::text) OR r2_object_key = ((((((((''sales-evidence/7d/''::text || owner_id::text) || ''/''::text) || market_id::text) || ''/''::text) || sale_id::text) || ''/''::text) || id::text) || ''.jpg''::text) OR r2_object_key = ((((((((''sales-evidence/7d/''::text || owner_id::text) || ''/''::text) || market_id::text) || ''/''::text) || sale_id::text) || ''/''::text) || id::text) || ''.jpeg''::text)) NOT VALID"},{"name":"sale_photo_evidence_r2_thumbnail_key_check","definition":"CHECK (r2_thumbnail_key IS NULL OR r2_thumbnail_key ~~ ''sales-evidence-thumbs/7d/%''::text AND r2_thumbnail_key !~~ ''%..%''::text AND r2_thumbnail_key !~~ ''%//%''::text)"},{"name":"sale_photo_evidence_r2_thumbnail_key_identity_check","definition":"CHECK (r2_thumbnail_key IS NULL OR r2_thumbnail_key = ((((((((''sales-evidence-thumbs/7d/''::text || owner_id::text) || ''/''::text) || market_id::text) || ''/''::text) || sale_id::text) || ''/''::text) || id::text) || ''.webp''::text) OR r2_thumbnail_key = ((((((((''sales-evidence-thumbs/7d/''::text || owner_id::text) || ''/''::text) || market_id::text) || ''/''::text) || sale_id::text) || ''/''::text) || id::text) || ''.jpg''::text) OR r2_thumbnail_key = ((((((((''sales-evidence-thumbs/7d/''::text || owner_id::text) || ''/''::text) || market_id::text) || ''/''::text) || sale_id::text) || ''/''::text) || id::text) || ''.jpeg''::text)) NOT VALID"},{"name":"sale_photo_evidence_sale_id_fkey","definition":"FOREIGN KEY (sale_id) REFERENCES events(id) ON DELETE CASCADE"},{"name":"sale_photo_evidence_status_check","definition":"CHECK (status = ANY (ARRAY[''not_required''::text, ''pending_capture''::text, ''capture_skipped''::text, ''captured_local''::text, ''uploading''::text, ''uploaded''::text, ''upload_failed''::text, ''expired''::text, ''waived_by_owner''::text]))"},{"name":"sale_photo_evidence_upload_lease_state_check","definition":"CHECK (status = ''uploading''::text AND upload_attempt_id IS NOT NULL AND upload_lease_expires_at IS NOT NULL OR status <> ''uploading''::text AND upload_lease_expires_at IS NULL)"},{"name":"sale_photo_evidence_waived_by_owner_id_fkey","definition":"FOREIGN KEY (waived_by_owner_id) REFERENCES profiles(id) ON DELETE SET NULL"},{"name":"sale_photo_evidence_width_check","definition":"CHECK (width IS NULL OR width > 0)"}],"viewDefinition":null}'::jsonb),
('public.snapshots','{"rls":true,"kind":"r","grants":[{"grantee":"anon","privilege":"DELETE"},{"grantee":"anon","privilege":"INSERT"},{"grantee":"anon","privilege":"REFERENCES"},{"grantee":"anon","privilege":"SELECT"},{"grantee":"anon","privilege":"TRIGGER"},{"grantee":"anon","privilege":"TRUNCATE"},{"grantee":"anon","privilege":"UPDATE"},{"grantee":"authenticated","privilege":"DELETE"},{"grantee":"authenticated","privilege":"INSERT"},{"grantee":"authenticated","privilege":"REFERENCES"},{"grantee":"authenticated","privilege":"SELECT"},{"grantee":"authenticated","privilege":"TRIGGER"},{"grantee":"authenticated","privilege":"TRUNCATE"},{"grantee":"authenticated","privilege":"UPDATE"},{"grantee":"postgres","privilege":"DELETE"},{"grantee":"postgres","privilege":"INSERT"},{"grantee":"postgres","privilege":"REFERENCES"},{"grantee":"postgres","privilege":"SELECT"},{"grantee":"postgres","privilege":"TRIGGER"},{"grantee":"postgres","privilege":"TRUNCATE"},{"grantee":"postgres","privilege":"UPDATE"},{"grantee":"service_role","privilege":"DELETE"},{"grantee":"service_role","privilege":"INSERT"},{"grantee":"service_role","privilege":"REFERENCES"},{"grantee":"service_role","privilege":"SELECT"},{"grantee":"service_role","privilege":"TRIGGER"},{"grantee":"service_role","privilege":"TRUNCATE"},{"grantee":"service_role","privilege":"UPDATE"}],"columns":[{"name":"id","type":"uuid","nullable":false},{"name":"user_id","type":"uuid","nullable":false},{"name":"snapshot_at","type":"timestamp with time zone","nullable":false},{"name":"version","type":"integer","nullable":false},{"name":"data","type":"jsonb","nullable":false},{"name":"event_count","type":"integer","nullable":false},{"name":"last_event_id","type":"uuid","nullable":false},{"name":"data_size_bytes","type":"integer","nullable":true},{"name":"compressed_size_bytes","type":"integer","nullable":true},{"name":"compression_ratio","type":"numeric(5,2)","nullable":true},{"name":"created_at","type":"timestamp with time zone","nullable":true}],"forceRls":false,"policies":[{"name":"用戶只能刪除自己的快照","check":null,"roles":"{0}","using":"(auth.uid() = user_id)","command":"d","permissive":true},{"name":"用戶只能創建自己的快照","check":"(auth.uid() = user_id)","roles":"{0}","using":null,"command":"a","permissive":true},{"name":"用戶只能查看自己的快照","check":null,"roles":"{0}","using":"(auth.uid() = user_id)","command":"r","permissive":true}],"triggers":[],"constraints":[{"name":"snapshots_pkey","definition":"PRIMARY KEY (id)"},{"name":"snapshots_user_id_fkey","definition":"FOREIGN KEY (user_id) REFERENCES profiles(id) ON DELETE CASCADE"},{"name":"snapshots_user_version_unique","definition":"UNIQUE (user_id, version)"}],"viewDefinition":null}'::jsonb),
('public.staff_accessible_events','{"rls":false,"kind":"v","grants":[{"grantee":"authenticated","privilege":"DELETE"},{"grantee":"authenticated","privilege":"INSERT"},{"grantee":"authenticated","privilege":"REFERENCES"},{"grantee":"authenticated","privilege":"SELECT"},{"grantee":"authenticated","privilege":"TRIGGER"},{"grantee":"authenticated","privilege":"TRUNCATE"},{"grantee":"authenticated","privilege":"UPDATE"},{"grantee":"postgres","privilege":"DELETE"},{"grantee":"postgres","privilege":"INSERT"},{"grantee":"postgres","privilege":"REFERENCES"},{"grantee":"postgres","privilege":"SELECT"},{"grantee":"postgres","privilege":"TRIGGER"},{"grantee":"postgres","privilege":"TRUNCATE"},{"grantee":"postgres","privilege":"UPDATE"},{"grantee":"service_role","privilege":"DELETE"},{"grantee":"service_role","privilege":"INSERT"},{"grantee":"service_role","privilege":"REFERENCES"},{"grantee":"service_role","privilege":"SELECT"},{"grantee":"service_role","privilege":"TRIGGER"},{"grantee":"service_role","privilege":"TRUNCATE"},{"grantee":"service_role","privilege":"UPDATE"}],"columns":[{"name":"id","type":"uuid","nullable":true},{"name":"type","type":"text","nullable":true},{"name":"payload","type":"jsonb","nullable":true},{"name":"actor_id","type":"uuid","nullable":true},{"name":"market_id","type":"uuid","nullable":true},{"name":"timestamp","type":"timestamp with time zone","nullable":true},{"name":"metadata","type":"jsonb","nullable":true},{"name":"sync_status","type":"sync_status","nullable":true},{"name":"relationship_owner_id","type":"uuid","nullable":true},{"name":"permissions","type":"jsonb","nullable":true},{"name":"access_type","type":"text","nullable":true}],"forceRls":false,"policies":[],"triggers":[],"constraints":[],"viewDefinition":" SELECT id,\n    type,\n        CASE\n            WHEN access_type = ''owner''::text AND NOT subscription_read_paid(relationship_owner_id) THEN subscription_free_payload(payload)\n            WHEN access_type = ''staff''::text AND (COALESCE(permissions ->> ''infoLevel''::text, ''0''::text) <> ALL (ARRAY[''2''::text, ''3''::text])) THEN subscription_free_payload(subscription_staff_payload(payload))\n            WHEN access_type = ''staff''::text THEN subscription_staff_payload(payload)\n            ELSE payload\n        END AS payload,\n    actor_id,\n    market_id,\n    \"timestamp\",\n        CASE\n            WHEN access_type = ''staff''::text OR NOT subscription_read_paid(relationship_owner_id) THEN NULL::jsonb\n            ELSE metadata\n        END AS metadata,\n    sync_status,\n    relationship_owner_id,\n    permissions,\n    access_type\n   FROM ( SELECT e.id,\n            e.type,\n            sanitize_staff_event_payload(e.payload) AS payload,\n            e.actor_id,\n            e.market_id,\n            e.\"timestamp\",\n            e.metadata,\n            e.sync_status,\n            sr.owner_id AS relationship_owner_id,\n            sr.permissions,\n            ''staff''::text AS access_type\n           FROM events e\n             JOIN markets m ON m.id = e.market_id\n             JOIN staff_relationships sr ON sr.owner_id = m.owner_id\n          WHERE sr.staff_id = auth.uid() AND sr.status = ''active''::text AND COALESCE(m.is_deleted, false) = false\n        UNION ALL\n         SELECT e.id,\n            e.type,\n            sanitize_staff_event_payload(e.payload) AS payload,\n            e.actor_id,\n            e.market_id,\n            e.\"timestamp\",\n            e.metadata,\n            e.sync_status,\n            sr.owner_id AS relationship_owner_id,\n            sr.permissions,\n            ''staff''::text AS access_type\n           FROM events e\n             JOIN staff_relationships sr ON sr.owner_id = e.actor_id\n          WHERE sr.staff_id = auth.uid() AND sr.status = ''active''::text AND e.market_id IS NULL\n        UNION ALL\n         SELECT e.id,\n            e.type,\n            e.payload,\n            e.actor_id,\n            e.market_id,\n            e.\"timestamp\",\n            e.metadata,\n            e.sync_status,\n            e.actor_id AS relationship_owner_id,\n            ''{\"can_edit\": true, \"can_view\": true}''::jsonb AS permissions,\n            ''owner''::text AS access_type\n           FROM events e\n          WHERE e.actor_id = auth.uid() AND e.market_id IS NULL AND (EXISTS ( SELECT 1\n                   FROM markets owned_market\n                  WHERE owned_market.owner_id = auth.uid()))\n        UNION ALL\n         SELECT e.id,\n            e.type,\n            e.payload,\n            e.actor_id,\n            e.market_id,\n            e.\"timestamp\",\n            e.metadata,\n            e.sync_status,\n            m.owner_id AS relationship_owner_id,\n            ''{\"can_edit\": true, \"can_view\": true}''::jsonb AS permissions,\n            ''owner''::text AS access_type\n           FROM events e\n             JOIN markets m ON m.id = e.market_id\n          WHERE m.owner_id = auth.uid()) s\n  WHERE access_type = ''owner''::text AND relationship_owner_id = auth.uid() AND (subscription_read_paid(relationship_owner_id) OR subscription_foundation_event(type)) OR access_type = ''staff''::text AND subscription_read_staff(relationship_owner_id) AND ((COALESCE(permissions ->> ''infoLevel''::text, ''0''::text) = ANY (ARRAY[''2''::text, ''3''::text])) OR subscription_foundation_event(type));"}'::jsonb),
('public.staff_accessible_markets','{"rls":false,"kind":"v","grants":[{"grantee":"authenticated","privilege":"DELETE"},{"grantee":"authenticated","privilege":"INSERT"},{"grantee":"authenticated","privilege":"REFERENCES"},{"grantee":"authenticated","privilege":"SELECT"},{"grantee":"authenticated","privilege":"TRIGGER"},{"grantee":"authenticated","privilege":"TRUNCATE"},{"grantee":"authenticated","privilege":"UPDATE"},{"grantee":"postgres","privilege":"DELETE"},{"grantee":"postgres","privilege":"INSERT"},{"grantee":"postgres","privilege":"REFERENCES"},{"grantee":"postgres","privilege":"SELECT"},{"grantee":"postgres","privilege":"TRIGGER"},{"grantee":"postgres","privilege":"TRUNCATE"},{"grantee":"postgres","privilege":"UPDATE"},{"grantee":"service_role","privilege":"DELETE"},{"grantee":"service_role","privilege":"INSERT"},{"grantee":"service_role","privilege":"REFERENCES"},{"grantee":"service_role","privilege":"SELECT"},{"grantee":"service_role","privilege":"TRIGGER"},{"grantee":"service_role","privilege":"TRUNCATE"},{"grantee":"service_role","privilege":"UPDATE"}],"columns":[{"name":"id","type":"uuid","nullable":true},{"name":"owner_id","type":"uuid","nullable":true},{"name":"name","type":"text","nullable":true},{"name":"location","type":"text","nullable":true},{"name":"start_date","type":"date","nullable":true},{"name":"end_date","type":"date","nullable":true},{"name":"status","type":"text","nullable":true},{"name":"early_entry_enabled","type":"boolean","nullable":true},{"name":"early_entry_time","type":"time without time zone","nullable":true},{"name":"check_in_time","type":"time without time zone","nullable":true},{"name":"operating_start_time","type":"time without time zone","nullable":true},{"name":"operating_end_time","type":"time without time zone","nullable":true},{"name":"registration_fee","type":"numeric(10,2)","nullable":true},{"name":"booth_cost","type":"numeric(10,2)","nullable":true},{"name":"deposit","type":"numeric(10,2)","nullable":true},{"name":"table_rental","type":"numeric(10,2)","nullable":true},{"name":"chair_rental","type":"numeric(10,2)","nullable":true},{"name":"umbrella_rental","type":"numeric(10,2)","nullable":true},{"name":"tablecloth_rental","type":"numeric(10,2)","nullable":true},{"name":"commission_rate","type":"numeric(5,2)","nullable":true},{"name":"table_free","type":"boolean","nullable":true},{"name":"chair_free","type":"boolean","nullable":true},{"name":"umbrella_free","type":"boolean","nullable":true},{"name":"tablecloth_free","type":"boolean","nullable":true},{"name":"total_revenue","type":"numeric(10,2)","nullable":true},{"name":"total_profit","type":"numeric(10,2)","nullable":true},{"name":"total_interactions","type":"integer","nullable":true},{"name":"total_deals","type":"integer","nullable":true},{"name":"notes","type":"text","nullable":true},{"name":"created_at","type":"timestamp with time zone","nullable":true},{"name":"updated_at","type":"timestamp with time zone","nullable":true},{"name":"is_collaborative","type":"boolean","nullable":true},{"name":"operation_phase","type":"text","nullable":true},{"name":"is_deleted","type":"boolean","nullable":true},{"name":"sync_status","type":"sync_status","nullable":true},{"name":"relationship_owner_id","type":"uuid","nullable":true},{"name":"permissions","type":"jsonb","nullable":true},{"name":"access_type","type":"text","nullable":true},{"name":"sales_photo_evidence_required","type":"boolean","nullable":true},{"name":"operation_session_date","type":"date","nullable":true},{"name":"venue_id","type":"uuid","nullable":true},{"name":"schedule_id","type":"uuid","nullable":true},{"name":"session_origin","type":"text","nullable":true},{"name":"schedule_occurrence_key","type":"text","nullable":true},{"name":"schedule_revision","type":"integer","nullable":true},{"name":"schedule_occurrence_state","type":"text","nullable":true},{"name":"is_schedule_override","type":"boolean","nullable":true},{"name":"region_code","type":"text","nullable":true},{"name":"payment_deadline","type":"jsonb","nullable":true}],"forceRls":false,"policies":[],"triggers":[],"constraints":[],"viewDefinition":" SELECT id,\n    owner_id,\n    name,\n    location,\n    start_date,\n    end_date,\n    status,\n    early_entry_enabled,\n    early_entry_time,\n    check_in_time,\n    operating_start_time,\n    operating_end_time,\n    registration_fee,\n    booth_cost,\n    deposit,\n    table_rental,\n    chair_rental,\n    umbrella_rental,\n    tablecloth_rental,\n    commission_rate,\n    table_free,\n    chair_free,\n    umbrella_free,\n    tablecloth_free,\n        CASE\n            WHEN access_type = ''owner''::text AND NOT subscription_read_paid(owner_id) OR access_type = ''staff''::text AND (COALESCE(permissions ->> ''infoLevel''::text, ''0''::text) <> ALL (ARRAY[''2''::text, ''3''::text])) THEN NULL::numeric(10,2)\n            ELSE total_revenue\n        END AS total_revenue,\n        CASE\n            WHEN access_type = ''owner''::text AND NOT subscription_read_paid(owner_id) OR access_type = ''staff''::text AND (COALESCE(permissions ->> ''infoLevel''::text, ''0''::text) <> ALL (ARRAY[''2''::text, ''3''::text])) THEN NULL::numeric(10,2)\n            ELSE total_profit\n        END AS total_profit,\n        CASE\n            WHEN access_type = ''owner''::text AND NOT subscription_read_paid(owner_id) OR access_type = ''staff''::text AND (COALESCE(permissions ->> ''infoLevel''::text, ''0''::text) <> ALL (ARRAY[''2''::text, ''3''::text])) THEN NULL::integer\n            ELSE total_interactions\n        END AS total_interactions,\n        CASE\n            WHEN access_type = ''owner''::text AND NOT subscription_read_paid(owner_id) OR access_type = ''staff''::text AND (COALESCE(permissions ->> ''infoLevel''::text, ''0''::text) <> ALL (ARRAY[''2''::text, ''3''::text])) THEN NULL::integer\n            ELSE total_deals\n        END AS total_deals,\n    notes,\n    created_at,\n    updated_at,\n    is_collaborative,\n    operation_phase,\n    is_deleted,\n    sync_status,\n    relationship_owner_id,\n    permissions,\n    access_type,\n    sales_photo_evidence_required,\n    operation_session_date,\n    venue_id,\n    schedule_id,\n    session_origin,\n    schedule_occurrence_key,\n    schedule_revision,\n    schedule_occurrence_state,\n    is_schedule_override,\n    region_code,\n    payment_deadline\n   FROM ( SELECT m.id,\n            m.owner_id,\n            m.name,\n            m.location,\n            m.start_date,\n            m.end_date,\n            m.status,\n            m.early_entry_enabled,\n            m.early_entry_time,\n            m.check_in_time,\n            m.operating_start_time,\n            m.operating_end_time,\n            NULL::numeric(10,2) AS registration_fee,\n            NULL::numeric(10,2) AS booth_cost,\n            NULL::numeric(10,2) AS deposit,\n            m.table_rental,\n            m.chair_rental,\n            m.umbrella_rental,\n            m.tablecloth_rental,\n            NULL::numeric(5,2) AS commission_rate,\n            m.table_free,\n            m.chair_free,\n            m.umbrella_free,\n            m.tablecloth_free,\n            m.total_revenue,\n            NULL::numeric(10,2) AS total_profit,\n            m.total_interactions,\n            m.total_deals,\n            m.notes,\n            m.created_at,\n            m.updated_at,\n            m.is_collaborative,\n            m.operation_phase,\n            m.is_deleted,\n            m.sync_status,\n            sr.owner_id AS relationship_owner_id,\n            sr.permissions,\n            ''staff''::text AS access_type,\n            m.sales_photo_evidence_required,\n            m.operation_session_date,\n            m.venue_id,\n            m.schedule_id,\n            m.session_origin,\n            m.schedule_occurrence_key,\n            m.schedule_revision,\n            m.schedule_occurrence_state,\n            m.is_schedule_override,\n            m.region_code,\n            m.payment_deadline\n           FROM markets m\n             JOIN staff_relationships sr ON sr.owner_id = m.owner_id\n          WHERE sr.staff_id = auth.uid() AND sr.status = ''active''::text AND COALESCE(m.is_deleted, false) = false\n        UNION ALL\n         SELECT m.id,\n            m.owner_id,\n            m.name,\n            m.location,\n            m.start_date,\n            m.end_date,\n            m.status,\n            m.early_entry_enabled,\n            m.early_entry_time,\n            m.check_in_time,\n            m.operating_start_time,\n            m.operating_end_time,\n            m.registration_fee,\n            m.booth_cost,\n            m.deposit,\n            m.table_rental,\n            m.chair_rental,\n            m.umbrella_rental,\n            m.tablecloth_rental,\n            m.commission_rate,\n            m.table_free,\n            m.chair_free,\n            m.umbrella_free,\n            m.tablecloth_free,\n            m.total_revenue,\n            m.total_profit,\n            m.total_interactions,\n            m.total_deals,\n            m.notes,\n            m.created_at,\n            m.updated_at,\n            m.is_collaborative,\n            m.operation_phase,\n            m.is_deleted,\n            m.sync_status,\n            m.owner_id AS relationship_owner_id,\n            ''{\"can_edit\": true, \"can_view\": true}''::jsonb AS permissions,\n            ''owner''::text AS access_type,\n            m.sales_photo_evidence_required,\n            m.operation_session_date,\n            m.venue_id,\n            m.schedule_id,\n            m.session_origin,\n            m.schedule_occurrence_key,\n            m.schedule_revision,\n            m.schedule_occurrence_state,\n            m.is_schedule_override,\n            m.region_code,\n            m.payment_deadline\n           FROM markets m\n          WHERE m.owner_id = auth.uid()) s\n  WHERE access_type = ''owner''::text AND owner_id = auth.uid() OR access_type = ''staff''::text AND subscription_read_staff(relationship_owner_id);"}'::jsonb),
('public.staff_accessible_products','{"rls":false,"kind":"v","grants":[{"grantee":"authenticated","privilege":"DELETE"},{"grantee":"authenticated","privilege":"INSERT"},{"grantee":"authenticated","privilege":"REFERENCES"},{"grantee":"authenticated","privilege":"SELECT"},{"grantee":"authenticated","privilege":"TRIGGER"},{"grantee":"authenticated","privilege":"TRUNCATE"},{"grantee":"authenticated","privilege":"UPDATE"},{"grantee":"postgres","privilege":"DELETE"},{"grantee":"postgres","privilege":"INSERT"},{"grantee":"postgres","privilege":"REFERENCES"},{"grantee":"postgres","privilege":"SELECT"},{"grantee":"postgres","privilege":"TRIGGER"},{"grantee":"postgres","privilege":"TRUNCATE"},{"grantee":"postgres","privilege":"UPDATE"},{"grantee":"service_role","privilege":"DELETE"},{"grantee":"service_role","privilege":"INSERT"},{"grantee":"service_role","privilege":"REFERENCES"},{"grantee":"service_role","privilege":"SELECT"},{"grantee":"service_role","privilege":"TRIGGER"},{"grantee":"service_role","privilege":"TRUNCATE"},{"grantee":"service_role","privilege":"UPDATE"}],"columns":[{"name":"id","type":"uuid","nullable":true},{"name":"market_id","type":"uuid","nullable":true},{"name":"name","type":"text","nullable":true},{"name":"category","type":"text","nullable":true},{"name":"price","type":"numeric(10,2)","nullable":true},{"name":"cost","type":"numeric(10,2)","nullable":true},{"name":"icon_name","type":"text","nullable":true},{"name":"color_code","type":"text","nullable":true},{"name":"stock","type":"integer","nullable":true},{"name":"unlimited_stock","type":"boolean","nullable":true},{"name":"is_active","type":"boolean","nullable":true},{"name":"total_sold","type":"integer","nullable":true},{"name":"description","type":"text","nullable":true},{"name":"created_at","type":"timestamp with time zone","nullable":true},{"name":"updated_at","type":"timestamp with time zone","nullable":true},{"name":"owner_id","type":"uuid","nullable":true},{"name":"is_shared","type":"boolean","nullable":true},{"name":"relationship_owner_id","type":"uuid","nullable":true},{"name":"permissions","type":"jsonb","nullable":true},{"name":"access_type","type":"text","nullable":true}],"forceRls":false,"policies":[],"triggers":[],"constraints":[],"viewDefinition":" SELECT id,\n    market_id,\n    name,\n    category,\n        CASE\n            WHEN access_type = ''owner''::text AND NOT subscription_read_paid(owner_id) OR access_type = ''staff''::text AND (COALESCE(permissions ->> ''infoLevel''::text, ''0''::text) <> ALL (ARRAY[''2''::text, ''3''::text])) THEN NULL::numeric(10,2)\n            ELSE price\n        END AS price,\n    cost,\n    icon_name,\n    color_code,\n        CASE\n            WHEN access_type = ''owner''::text AND NOT subscription_read_paid(owner_id) OR access_type = ''staff''::text AND (COALESCE(permissions ->> ''infoLevel''::text, ''0''::text) <> ALL (ARRAY[''2''::text, ''3''::text])) THEN NULL::integer\n            ELSE stock\n        END AS stock,\n    unlimited_stock,\n    is_active,\n        CASE\n            WHEN access_type = ''owner''::text AND NOT subscription_read_paid(owner_id) OR access_type = ''staff''::text AND (COALESCE(permissions ->> ''infoLevel''::text, ''0''::text) <> ALL (ARRAY[''2''::text, ''3''::text])) THEN NULL::integer\n            ELSE total_sold\n        END AS total_sold,\n    description,\n    created_at,\n    updated_at,\n    owner_id,\n    is_shared,\n    relationship_owner_id,\n    permissions,\n    access_type\n   FROM ( SELECT p.id,\n            p.market_id,\n            p.name,\n            p.category,\n            p.price,\n            NULL::numeric(10,2) AS cost,\n            p.icon_name,\n            p.color_code,\n            p.stock,\n            p.unlimited_stock,\n            p.is_active,\n            p.total_sold,\n            p.description,\n            p.created_at,\n            p.updated_at,\n            p.owner_id,\n            p.is_shared,\n            sr.owner_id AS relationship_owner_id,\n            sr.permissions,\n            ''staff''::text AS access_type\n           FROM products p\n             JOIN staff_relationships sr ON sr.owner_id = p.owner_id\n          WHERE sr.staff_id = auth.uid() AND sr.status = ''active''::text AND p.is_active = true\n        UNION ALL\n         SELECT p.id,\n            p.market_id,\n            p.name,\n            p.category,\n            p.price,\n            p.cost,\n            p.icon_name,\n            p.color_code,\n            p.stock,\n            p.unlimited_stock,\n            p.is_active,\n            p.total_sold,\n            p.description,\n            p.created_at,\n            p.updated_at,\n            p.owner_id,\n            p.is_shared,\n            p.owner_id AS relationship_owner_id,\n            ''{\"can_edit\": true, \"can_view\": true}''::jsonb AS permissions,\n            ''owner''::text AS access_type\n           FROM products p\n          WHERE p.owner_id = auth.uid() AND p.is_active = true) s\n  WHERE access_type = ''owner''::text AND subscription_read_owner_paid(owner_id) OR access_type = ''staff''::text AND subscription_read_staff(relationship_owner_id);"}'::jsonb),
